mapper.select:
SELECT id, law_code AS lawCode, law_name AS lawName, article_no AS articleNo, article_seq AS articleSeq, content, effective_date AS effectiveDate, expire_date AS expireDate, status FROM law_item WHERE id IN
#{id}
AND status = 'active' AND is_enabled = 1
AND law_code = #{lawCode}

SELECT id, law_code AS lawCode, law_name AS lawName, article_no AS articleNo, article_seq AS articleSeq, content, effective_date AS effectiveDate, expire_date AS expireDate, status FROM law_item WHERE status = 'active' AND is_enabled = 1 AND (article_no = #{articleNo}
OR article_seq = #{articleSeq} )
AND (law_name LIKE CONCAT('%', #{lawNameHint}, '%') OR law_code = #{lawNameHint})
AND law_code = #{lawCode}
ORDER BY article_seq ASC, id ASC LIMIT 20

SELECT id, law_code AS lawCode, law_name AS lawName, article_no AS articleNo, article_seq AS articleSeq, content, effective_date AS effectiveDate, expire_date AS expireDate, status FROM law_item WHERE status = 'active' AND is_enabled = 1 AND content LIKE CONCAT('%', #{kw}, '%')
AND law_code = #{lawCode}
ORDER BY article_seq ASC, id ASC LIMIT #{limit}

SELECT id, law_code AS lawCode, law_name AS lawName, article_no AS articleNo, article_seq AS articleSeq, content, effective_date AS effectiveDate, expire_date AS expireDate, status FROM law_item WHERE status = 'active' AND is_enabled = 1 AND keywords IS NOT NULL AND (
keywords LIKE CONCAT('%', #{term}, '%')
)
AND law_code = #{lawCode}
ORDER BY article_seq ASC, id ASC LIMIT #{limit}

SELECT id, law_code AS lawCode, law_name AS lawName, article_no AS articleNo, article_seq AS articleSeq, content, effective_date AS effectiveDate, expire_date AS expireDate, status FROM law_item WHERE status = 'active' AND is_enabled = 1
AND law_code = #{lawCode}
ORDER BY article_seq ASC, id ASC LIMIT #{limit} OFFSET #{offset}
